mapper.select:
SELECT a.id, a.type_id, t.type_name, a.apply_reason, a.family_situation, a.special_type, a.special_proof, a.status, a.reviewer_id, ru.name AS reviewer_name, a.review_comment, a.review_time, a.student_id, s.student_no, s.name AS student_name, a.create_time, a.update_time FROM grant_application a LEFT JOIN grant_type t ON a.type_id = t.id LEFT JOIN sys_user ru ON a.reviewer_id = ru.user_id AND ru.role = 1 LEFT JOIN student s ON a.student_id = s.id
AND a.student_id = #{studentId}
AND a.status = #{status}
AND a.type_id = #{typeId}
AND (s.student_no LIKE CONCAT('%', #{keyword}, '%') OR s.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY a.create_time DESC
